pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        Helper helper = new Helper();
        bool refRevert;
        bool mutRevert;
        try helper.callSetL1BlockValues(address(c), _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            refRevert = false;
        } catch {
            refRevert = true;
        }
        // The mutant is equivalent to compiling the modified contract, which we don't have here.
        // But we can simulate its behavior: for any contract caller, the mutant reverts only if the caller is address(0).
        // Since helper is a contract, its address is not zero, so the mutant would NOT revert.
        // The reference reverts because depositorAccount is address(0) and msg.sender != address(0).
        assertTrue(refRevert);
    }
}

contract Helper {
    function callSetL1BlockValues(address target, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) external {
        C(target).setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }
}

